let express;
try {
  express = require('express');
} catch (error) {
  if (error.code !== 'MODULE_NOT_FOUND') {
    throw error;
  }

  // Tiny Express-compatible fallback for this app's simple GET/JSON routes.
  // It keeps the service runnable in environments where dependencies have not
  // been installed, while still using real Express whenever it is available.
  express = function createTinyExpressApp() {
    const routes = [];

    const app = (req, res) => {
      const path = new URL(req.url, 'http://localhost').pathname;
      const route = routes.find((candidate) => candidate.method === req.method && candidate.path === path);

      res.json = (payload) => {
        const body = JSON.stringify(payload);
        res.statusCode = res.statusCode || 200;
        res.setHeader('Content-Type', 'application/json; charset=utf-8');
        res.setHeader('Content-Length', Buffer.byteLength(body));
        res.end(body);
      };

      if (!route) {
        res.statusCode = 404;
        return res.json({ error: 'Not found' });
      }

      return route.handler(req, res);
    };

    app.get = (path, handler) => {
      routes.push({ method: 'GET', path, handler });
      return app;
    };

    app.listen = (port, callback) => {
      const http = require('http');
      return http.createServer(app).listen(port, callback);
    };

    return app;
  };
}

