const assert = require('assert');
const http = require('http');
const app = require('./app');

const server = http.createServer(app);

function request(path) {
  return new Promise((resolve, reject) => {
    const { port } = server.address();
    http.get({ hostname: '127.0.0.1', port, path }, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', chunk => { body += chunk; });
      res.on('end', () => {
        resolve({ statusCode: res.statusCode, headers: res.headers, body });
      });
    }).on('error', reject);
  });
}

server.listen(0, async () => {
  try {
    const health = await request('/health');
    assert.strictEqual(health.statusCode, 200);
    assert.strictEqual(JSON.parse(health.body).status, 'ok');

    const users = await request('/users');
    assert.strictEqual(users.statusCode, 200);
    const parsedUsers = JSON.parse(users.body);
    assert.strictEqual(parsedUsers.length, 2);
    assert.strictEqual(parsedUsers[0].name, 'Alice');

    console.log('CI checks passed');
  } catch (error) {
    console.error(error);
    process.exitCode = 1;
  } finally {
    server.close();
  }
});
