const http = require('http');

const routes = new Map();

function sendJson(res, statusCode, body) {
  const payload = JSON.stringify(body);
  res.writeHead(statusCode, {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function app(req, res) {
  const methodRoutes = routes.get(req.method);
  const url = new URL(req.url, 'http://localhost');
  const handler = methodRoutes && methodRoutes.get(url.pathname);

  if (!handler) {
    return sendJson(res, 404, { error: 'Not Found' });
  }

  res.json = (body) => sendJson(res, res.statusCode || 200, body);
  return handler(req, res);
}

app.get = (path, handler) => {
  if (!routes.has('GET')) {
    routes.set('GET', new Map());
  }
  routes.get('GET').set(path, handler);
};

app.listen = (...args) => http.createServer(app).listen(...args);

