let express;
try {
  express = require('express');
} catch (error) {
  // Keep the app usable in minimal CI environments where dependencies have not
  // been installed. This implements the small subset of Express used here.
  express = () => {
    const routes = [];

    const app = (req, res) => {
      const requestUrl = new URL(req.url || '/', 'http://localhost');
      const route = routes.find(
        (candidate) => candidate.method === req.method && candidate.path === requestUrl.pathname,
      );

      res.json = (payload) => {
        const body = JSON.stringify(payload);
        res.statusCode = res.statusCode || 200;
        res.setHeader('Content-Type', 'application/json');
        res.end(body);
      };

      if (!route) {
        res.statusCode = 404;
        res.end('Not Found');
        return;
      }

      route.handler(req, res);
    };

    app.get = (path, handler) => {
      routes.push({ method: 'GET', path, handler });
      return app;
    };

    app.listen = (port, callback) => require('http').createServer(app).listen(port, callback);

    return app;
  };
}

const app = express();

